using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.IsNotNull(responseText);
        Assert.IsTrue(responseText.Length > 0, "Response should not be empty.");

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsCoherentResponse));

        var evaluator = scenario.GetEvaluator<CoherenceEvaluator>();
        var result = await evaluator.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, responseText));

        var metric = result.Get<NumericMetric>(CoherenceEvaluator.CoherenceMetricName);
        Assert.IsTrue(metric.Value >= 3, $"Coherence score {metric.Value} is below threshold.");
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what .NET Aspire is in one sentence.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.IsNotNull(responseText);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsRelevantResponse));

        var evaluator = scenario.GetEvaluator<RelevanceEvaluator>();
        var result = await evaluator.EvaluateAsync(
            messages,
            new ChatMessage(ChatRole.Assistant, responseText));

        var metric = result.Get<NumericMetric>(RelevanceEvaluator.RelevanceMetricName);
        Assert.IsTrue(metric.Value >= 3, $"Relevance score {metric.Value} is below threshold.");
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Path.GetTempPath(), "MyApp.Evaluation"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
            ]);
    }
}

